import { useContext, useState } from "react";
import { ComplaintContext } from "../context/ComplaintContext";
import "../styles/global.css";

function AuthorityDashboard() {
  const { complaints, updateStatus } = useContext(ComplaintContext);
  const [filter, setFilter] = useState("All");

  const filtered =
    filter === "All"
      ? complaints
      : complaints.filter((c) => c.status === filter);

  const sorted = [...filtered].sort((a, b) => {
    const order = { High: 1, Medium: 2, Low: 3 };
    return order[a.severity] - order[b.severity];
  });

  const total = complaints.length;
  const pending = complaints.filter((c) => c.status === "Pending").length;
  const resolved = complaints.filter((c) => c.status === "Resolved").length;

  return (
    <div className="admin-bg">

      <div className="admin-header">
        <h2>Authority Control Panel</h2>

        <select onChange={(e) => setFilter(e.target.value)}>
          <option>All</option>
          <option>Pending</option>
          <option>Approved</option>
          <option>Rejected</option>
          <option>Resolved</option>
        </select>
      </div>

      {/* ⭐ Analytics */}
      <div className="analytics">
        <div className="stat">Total: {total}</div>
        <div className="stat">Pending: {pending}</div>
        <div className="stat">Resolved: {resolved}</div>
      </div>

      {/* ⭐ Complaint List */}
      <div className="admin-list">
        {sorted.length === 0 && <p>No complaints</p>}

        {sorted.map((c) => (
          <div key={c.id} className="admin-card">

            <div className="admin-top">
              <h3>{c.department}</h3>
              <span className={`sev ${c.severity}`}>
                {c.severity}
              </span>
            </div>

            <p><b>Category:</b> {c.category}</p>
            <p><b>Description:</b> {c.desc}</p>
            <p><b>Status:</b> {c.status}</p>

            {c.image && (
              <img src={c.image} className="img-preview" alt="complaint"/>
            )}

            {/* ⭐ Status Buttons */}
            <div className="admin-actions">
              <button onClick={() => updateStatus(c.id, "Approved")}>
                Approve
              </button>

              <button onClick={() => updateStatus(c.id, "Rejected")}>
                Reject
              </button>

              <button onClick={() => updateStatus(c.id, "Resolved")}>
                Resolve
              </button>
            </div>

          </div>
        ))}
      </div>
    </div>
  );
}

export default AuthorityDashboard;
